/// Narrow a `usize` byte offset or length to the `u32` `oxc-miette` stores.
///
/// Files larger than 4 GiB are not a supported input, so this saturates.
#[must_use]
pub fn clamp_offset(value: usize) -> u32 {
    u32::try_from(value).unwrap_or(u32::MAX)
}

/// Wrap help and note text without splitting URLs.
/// `textwrap` treats `/` and `-` as break opportunities, so a URL is not one word.
#[must_use]
pub fn graphical_handler(theme: GraphicalTheme) -> GraphicalReportHandler {
    GraphicalReportHandler::new_themed(theme)
        .with_word_separator(textwrap::WordSeparator::AsciiSpace)
        .with_word_splitter(textwrap::WordSplitter::NoHyphenation)
        .with_break_words(false)
}

/// Build a [`SourceSpan`] from `usize` byte offsets.
///
/// For a span covering a slice of the source, use [`LintContext::source_span`] instead:
#[must_use]
pub fn span(start: usize, len: usize) -> SourceSpan {
    SourceSpan::new(clamp_offset(start).into(), clamp_offset(len))
}

/// A single lint diagnostic without source code.
///
/// Source code is attached at render time by [`FileDiagnostics::reports`].
#[derive(Debug, Clone, Diagnostic, thiserror::Error)]
#[error("{message}")]
pub struct LintDiagnostic {
    /// Rule code (e.g., "invalid-attr-value").
    #[diagnostic(code)]
    pub code: &'static str,
    /// Human-readable error message.
    pub message: Cow<'static, str>,
    /// Source span where the error occurred.
    #[label("here")]
    pub span: SourceSpan,
    /// Optional help text with suggestions.
    #[help]
    pub help: Option<Cow<'static, str>>,
    /// Optional fix attached to the diagnostic.
    ///
    /// Stored on the diagnostic; applicability gating happens at apply time.
    pub fix: Option<Fix>,
    /// Optional short imperative summary of the fix.
    ///
    /// Stored separately from `help` so the renderer can mark it as fix-related
    /// (and so a rule's `help()` and `fix_title()` don't fight for the same field).
    pub fix_title: Option<&'static str>,
}

/// A collection of lint diagnostics for a single file.
///
/// The source is held once, behind an [`Arc`], and shared with every
/// diagnostic at render time.
#[derive(Debug, Clone)]
pub struct FileDiagnostics {
    /// The source code of the file.
    pub source_code: NamedSource<Arc<str>>,
    /// All diagnostics found in this file.
    pub diagnostics: Vec<LintDiagnostic>,
}

impl FileDiagnostics {
    /// Create a new `FileDiagnostics` from source code and diagnostics.
    #[must_use]
    pub fn new(
        name: impl AsRef<str>,
        source: impl Into<Arc<str>>,
        diagnostics: Vec<LintDiagnostic>,
    ) -> Self {
        Self {
            source_code: NamedSource::new(name, source.into()),
            diagnostics,
        }
    }

    /// Create a new empty `FileDiagnostics`.
    ///
    /// The empty source is shared: this is on the path of every clean file.
    #[must_use]
    pub fn empty() -> Self {
        static EMPTY: LazyLock<Arc<str>> = LazyLock::new(|| Arc::from(""));
        Self {
            source_code: NamedSource::new("", Arc::clone(&EMPTY)),
            diagnostics: Vec::new(),
        }
    }

    /// Returns true if there are no diagnostics.
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        self.diagnostics.is_empty()
    }

    /// Returns the number of diagnostics.
    #[must_use]
    pub const fn len(&self) -> usize {
        self.diagnostics.len()
    }

    /// Each diagnostic paired with the file's source, ready to render on its own.
    pub fn reports(&self) -> impl Iterator<Item = Report> + '_ {
        self.diagnostics.iter().map(|diagnostic| {
            Report::new(diagnostic.clone()).with_source_code(self.source_code.clone())
        })
    }

    /// Render each diagnostic as a standalone block, propagating `handler` errors.
    pub fn render(&self, handler: &GraphicalReportHandler, out: &mut String) -> fmt::Result {
        self.reports()
            .try_for_each(|report| handler.render_report(out, report.as_ref()))
    }
}

/// A parsed template: the AST, the source it borrows, and the profile it was parsed with.
///
/// Only [`parse`] builds one, so a check can never run against a source or a profile
/// the AST was not built from.
#[derive(Debug)]
pub struct Parsed<'a> {
    source: &'a str,
    language: Language,
    ast: Root<'a>,
}

impl<'a> Parsed<'a> {
    /// The AST.
    #[must_use]
    pub const fn ast(&self) -> &Root<'a> {
        &self.ast
    }

    /// The source the AST borrows.
    #[must_use]
    pub const fn source(&self) -> &'a str {
        self.source
    }

    /// The profile the source was parsed with.
    #[must_use]
    pub const fn language(&self) -> Language {
        self.language
    }

    /// Check the AST for lint errors.
    ///
    /// Traverses the AST and runs all enabled lint rules, returning any diagnostics found.
    ///
    /// `path` enables path-aware rules; pass [`None`] when linting a buffer without a
    /// backing file.
    #[must_use]
    pub fn check(&self, settings: &Settings, path: Option<&Path>) -> Vec<LintDiagnostic> {
        let mut checker = Checker::new(self.source, settings, self.language, path);
        // Walk the ast and collect diagnostics.
        checker.visit_root(&self.ast);

        // Collect ignore comments and drop the ignored diagnostics.
        let mut ignore_comments = suppression::collect_ignore_comments(&self.ast, &checker);
        checker.visit_ignore_comments(&ignore_comments);
        suppression::record_matches(&checker, &mut ignore_comments);
        checker.visit_unused_ignore_codes(&ignore_comments);
        suppression::drop_ignored_diagnostics(&checker, &ignore_comments);
        checker.into_diagnostics()
    }

    /// Check, then apply the fixes that meet `threshold` in a single pass.
    #[must_use]
    pub fn fix(
        &self,
        settings: &Settings,
        threshold: Applicability,
        path: Option<&Path>,
    ) -> ApplyResult {
        apply_fixes(self.source, &self.check(settings, path), threshold)
    }
}

/// Parse `source`, treating each of `custom_blocks` as a `{% tag %}...{% endtag %}` block.
///
/// The single door to the parser: every consumer (check, fix, playground,
/// benches, tests) must parse with the same configuration or lint on a
/// different AST than the one the formatter sees.
pub fn parse<'a>(
    source: &'a str,
    language: Language,
    custom_blocks: &[String],
) -> Result<Parsed<'a>, SyntaxError> {
    Ok(Parsed {
        source,
        language,
        ast: Parser::new(source, language, custom_blocks.to_vec()).parse_root()?,
    })
}

/// Parse and lint `source` in one call.
///
/// `path` is forwarded to path-aware rules; pass [`None`] when there is no backing file.
pub fn lint_source(
    source: &str,
    language: Language,
    custom_blocks: &[String],
    settings: &Settings,
    path: Option<&Path>,
) -> Result<Vec<LintDiagnostic>, SyntaxError> {
    Ok(parse(source, language, custom_blocks)?.check(settings, path))
}

/// A completed [`lint_text`] run.
#[derive(Debug, Default)]
pub struct LintOutcome {
    /// The rewritten source, set only when fixes changed it: write exactly when this is [`Some`].
    pub fixed: Option<String>,
    /// Diagnostics left over, span-aligned to [`Self::fixed`] when there is one.
    pub diagnostics: Vec<LintDiagnostic>,
    /// Fixes applied.
    pub applied_count: usize,
    /// Per-rule applied summaries, for `--show-fixes`.
    pub applied_by_rule: FxHashMap<&'static str, RuleFixSummary>,
}

/// Lint `source`, applying fixes up to the given threshold when `fix` is [`Some`].
///
/// Returns [`None`] when a leading `file-ignore[invalid-syntax]` comment quarantines a file
/// that does not parse, like the formatter's `format_text`. The legacy bare directive,
/// which quarantines too, is still reported so that it gets migrated.
pub fn lint_text(
    source: &str,
    settings: &Settings,
    language: Language,
    custom_blocks: &[String],
    fix: Option<Applicability>,
    path: Option<&Path>,
) -> Result<Option<LintOutcome>, SyntaxError> {
    let check_only = || {
        lint_source(source, language, custom_blocks, settings, path).map(|diagnostics| {
            LintOutcome {
                diagnostics,
                ..LintOutcome::default()
            }
        })
    };
    let result = match fix
        .map(|threshold| lint_fix(source, settings, language, custom_blocks, threshold, path))
    {
        Some(Ok(result)) => Ok(LintOutcome {
            // The compare is skipped when nothing was applied: `source` is then a plain clone.
            fixed: (result.applied_count > 0 && result.source != source).then_some(result.source),
            diagnostics: result.remaining_diagnostics,
            applied_count: result.applied_count,
            applied_by_rule: result.applied_by_rule,
        }),
        Some(Err(FixerError::InitialParse(err))) => Err(err),
        Some(Err(FixerError::SyntaxRegression { iteration, .. })) => {
            tracing::error!(
                "Fix introduced a syntax error in {} at iteration {iteration}, leaving file unchanged",
                path.unwrap_or_else(|| Path::new("<source>")).display()
            );
            check_only()
        }
        None => check_only(),
    };
    match result {
        // `file-ignore[invalid-syntax]` quarantines the file instead of reporting.
        Err(_) if FileIgnores::parse(source).invalid_syntax => {
            Ok(lint_quarantined(source, settings, language, fix, path))
        }
        other => other.map(Some),
    }
}

/// Lint the one thing a quarantined file has without an AST: its leading comment, which only
/// `deprecated-ignore` would ever migrate. [`None`] when that leaves nothing to report.
fn lint_quarantined(
    source: &str,
    settings: &Settings,
    language: Language,
    fix: Option<Applicability>,
    path: Option<&Path>,
) -> Option<LintOutcome> {
    let checker = Checker::new(source, settings, language, path);
    if checker.is_rule_enabled(Rule::DeprecatedIgnore) {
        rules::suspicious::deprecated_ignore::check_quarantined(&checker);
    }
    let diagnostics = checker.into_diagnostics();
    if diagnostics.is_empty() {
        return None;
    }
    let applied = fix.map(|threshold| apply_fixes(source, &diagnostics, threshold));
    let Some(applied) = applied.filter(|applied| applied.applied_count > 0) else {
        return Some(LintOutcome {
            diagnostics,
            ..LintOutcome::default()
        });
    };
    // The rewritten comment still quarantines the file: nothing is left to report or iterate on.
    let summaries = applied.applied_fixes.iter().map(|fix| {
        let summary = RuleFixSummary {
            count: 1,
            fix_title: fix.fix_title,
        };
        (fix.code, summary)
    });
    Some(LintOutcome {
        fixed: Some(applied.output),
        applied_count: applied.applied_count,
        applied_by_rule: summaries.collect(),
        ..LintOutcome::default()
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn quarantine_covers_check_and_fix() {
        let settings = Settings::all();
        let quarantined = "{# djangofmt: file-ignore[invalid-syntax] #}\n<div>";
        for fix in [None, Some(Applicability::Safe)] {
            let lint = |source| lint_text(source, &settings, Language::Jinja, &[], fix, None);
            assert!(
                lint(quarantined).is_ok_and(|outcome| outcome.is_none()),
                "{fix:?}"
            );
            assert!(lint("<div>").is_err(), "{fix:?}");
        }
    }

    #[test]
    fn quarantining_legacy_directive_is_migrated() {
        let settings = Settings::all();
        let lint = |source: &str, fix| {
            lint_text(source, &settings, Language::Jinja, &[], fix, None)
                .unwrap()
                .unwrap_or_default()
        };
        let legacy = "{# djangofmt:ignore #}\n<div>";
        assert_eq!(lint(legacy, None).diagnostics[0].code, "deprecated-ignore");

        // Not `file-ignore[format]`, which would surface the parse error the directive was hiding.
        let fixed = lint(legacy, Some(Applicability::Safe)).fixed.unwrap();
        assert_eq!(fixed, "{# djangofmt: file-ignore[invalid-syntax] #}\n<div>");
        assert!(lint(&fixed, None).diagnostics.is_empty());
    }

    #[test]
    fn path_aware_rules_are_skipped_without_a_path() {
        let settings = Settings::all();
        let source = "{% partialdef card %}<span>A card</span>{% endpartialdef %}\n\
                      {% include \"tpl.html#card\" %}";
        let codes = |path| {
            lint_source(source, Language::Jinja, &[], &settings, path)
                .unwrap()
                .into_iter()
                .map(|diagnostic| diagnostic.code)
                .collect::<Vec<_>>()
        };

        assert!(codes(Some(Path::new("tpl.html"))).contains(&"same-file-partial-include"));
        assert!(!codes(None).contains(&"same-file-partial-include"));
    }
}
